"""A small arithmetic expression evaluator.

The evaluator intentionally uses a hand-written tokenizer and recursive-descent
parser rather than Python's ``eval``/``ast`` machinery.
"""


class CalcError(ValueError):
    """Raised for invalid expressions or expression evaluation errors."""


_NUMBER = "NUMBER"
_IDENT = "IDENT"
_OP = "OP"
_LPAREN = "LPAREN"
_RPAREN = "RPAREN"
_COMMA = "COMMA"
_EOF = "EOF"


class _Token:
    __slots__ = ("kind", "value", "pos")

    def __init__(self, kind, value, pos):
        self.kind = kind
        self.value = value
        self.pos = pos

    def __repr__(self):
        return "_Token({!r}, {!r}, {!r})".format(
            self.kind, self.value, self.pos
        )


def _tokenize(expr):
    """Turn *expr* into a list of tokens, ending with an EOF token."""
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        ch = expr[i]

        if ch.isspace():
            i += 1
            continue

        if ch.isdigit() or (ch == "." and i + 1 < n and expr[i + 1].isdigit()):
            start = i
            if ch == ".":
                # A decimal beginning with a decimal point, such as ".5".
                i += 1
                while i < n and expr[i].isdigit():
                    i += 1
                text = expr[start:i]
                tokens.append(_Token(_NUMBER, float(text), start))
            else:
                while i < n and expr[i].isdigit():
                    i += 1
                if i < n and expr[i] == ".":
                    # A decimal such as "3.5".  Note that "1." is accepted as
                    # a decimal too, just as Python's float literal syntax is.
                    i += 1
                    while i < n and expr[i].isdigit():
                        i += 1
                    tokens.append(_Token(_NUMBER, float(expr[start:i]), start))
                else:
                    tokens.append(_Token(_NUMBER, int(expr[start:i]), start))
            continue

        if ch.isalpha() or ch == "_":
            start = i
            i += 1
            while i < n and (expr[i].isalnum() or expr[i] == "_"):
                i += 1
            tokens.append(_Token(_IDENT, expr[start:i], start))
            continue

        # Two-character operators must be checked before their one-character
        # counterparts.
        if ch == "/" and i + 1 < n and expr[i + 1] == "/":
            tokens.append(_Token(_OP, "//", i))
            i += 2
            continue
        if ch == "*" and i + 1 < n and expr[i + 1] == "*":
            tokens.append(_Token(_OP, "**", i))
            i += 2
            continue

        if ch in "+-*/%":
            tokens.append(_Token(_OP, ch, i))
            i += 1
            continue
        if ch == "(":
            tokens.append(_Token(_LPAREN, ch, i))
            i += 1
            continue
        if ch == ")":
            tokens.append(_Token(_RPAREN, ch, i))
            i += 1
            continue
        if ch == ",":
            tokens.append(_Token(_COMMA, ch, i))
            i += 1
            continue

        raise CalcError("unexpected token {!r} at position {}".format(ch, i))

    tokens.append(_Token(_EOF, "", n))
    return tokens


class _Parser:
    def __init__(self, tokens, env):
        self.tokens = tokens
        self.env = env
        self.index = 0

    @property
    def current(self):
        return self.tokens[self.index]

    def advance(self):
        token = self.current
        self.index += 1
        return token

    def expect(self, kind, value=None):
        token = self.current
        if token.kind != kind or (value is not None and token.value != value):
            raise CalcError("unexpected token {!r}".format(token.value))
        return self.advance()

    def parse(self):
        if self.current.kind == _EOF:
            raise CalcError("empty input")

        value = self.parse_additive()

        if self.current.kind != _EOF:
            raise CalcError("unexpected token {!r}".format(self.current.value))
        return value

    def parse_additive(self):
        value = self.parse_multiplicative()
        while self.current.kind == _OP and self.current.value in ("+", "-"):
            op = self.advance().value
            rhs = self.parse_multiplicative()
            if op == "+":
                value = value + rhs
            else:
                value = value - rhs
        return value

    def parse_multiplicative(self):
        value = self.parse_unary()
        while self.current.kind == _OP and self.current.value in (
            "*",
            "/",
            "//",
            "%",
        ):
            op = self.advance().value
            rhs = self.parse_unary()
            try:
                if op == "*":
                    value = value * rhs
                elif op == "/":
                    value = value / rhs
                elif op == "//":
                    value = value // rhs
                else:
                    value = value % rhs
            except ZeroDivisionError:
                raise CalcError("division or modulo by zero")
        return value

    def parse_unary(self):
        if self.current.kind == _OP and self.current.value in ("+", "-"):
            op = self.advance().value
            operand = self.parse_unary()
            return operand if op == "+" else -operand
        return self.parse_power()

    def parse_power(self):
        base = self.parse_primary()
        if self.current.kind == _OP and self.current.value == "**":
            self.advance()
            # Parsing the exponent as a unary expression makes ** bind more
            # tightly than unary minus while remaining right-associative.
            exponent = self.parse_unary()
            try:
                return base ** exponent
            except ZeroDivisionError:
                raise CalcError("division by zero")
        return base

    def parse_primary(self):
        token = self.current

        if token.kind == _NUMBER:
            self.advance()
            return token.value

        if token.kind == _IDENT:
            name = token.value
            self.advance()
            if self.current.kind == _LPAREN:
                return self.parse_call(name)
            if name not in self.env:
                raise CalcError("unknown variable {!r}".format(name))
            return self.env[name]

        if token.kind == _LPAREN:
            self.advance()
            value = self.parse_additive()
            if self.current.kind != _RPAREN:
                raise CalcError("unbalanced parentheses")
            self.advance()
            return value

        raise CalcError("unexpected token {!r}".format(token.value))

    def parse_call(self, name):
        # The current token is the opening parenthesis.
        self.advance()
        args = []

        if self.current.kind == _RPAREN:
            self.advance()
        else:
            while True:
                args.append(self.parse_additive())
                if self.current.kind == _COMMA:
                    self.advance()
                    continue
                if self.current.kind == _RPAREN:
                    self.advance()
                    break
                raise CalcError("unbalanced parentheses")

        if name == "abs":
            if len(args) != 1:
                raise CalcError("abs() takes exactly one argument")
            return abs(args[0])
        if name in ("min", "max"):
            if not args:
                raise CalcError(
                    "{}() takes at least one argument".format(name)
                )
            return min(args) if name == "min" else max(args)

        raise CalcError("unknown function {!r}".format(name))


def evaluate(expr, env=None):
    """Evaluate an arithmetic expression.

    ``env`` supplies values for identifiers.  Invalid expressions and
    evaluation errors are reported as :class:`CalcError`.
    """
    if env is None:
        env = {}

    tokens = _tokenize(expr)
    return _Parser(tokens, env).parse()
